def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # The interior size selects the fill color: 3x3 -> 8, 5x5 -> 4, 7x7 -> 3.
    fill_by_side = {3: 8, 5: 4, 7: 3}
    for r1 in range(h - 2):
        for r2 in range(r1 + 2, h):
            for c1 in range(w - 2):
                for c2 in range(c1 + 2, w):
                    side_h, side_w = r2-r1-1, c2-c1-1
                    if side_h != side_w or side_h not in fill_by_side:
                        continue
                    if (all(grid[r1][c] == 2 for c in range(c1,c2+1)) and
                        all(grid[r2][c] == 2 for c in range(c1,c2+1)) and
                        all(grid[r][c1] == 2 for r in range(r1,r2+1)) and
                        all(grid[r][c2] == 2 for r in range(r1,r2+1))):
                        color = fill_by_side[side_h]
                        for r in range(r1+1,r2):
                            for c in range(c1+1,c2):
                                if grid[r][c] == 0:
                                    out[r][c] = color
    return out
